<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/Mail/Dispatch.php';
use TNL\Mail\Dispatch;use TNL\Mail\InternalMail;use TNL\Admin\Users;use TNL\Admin\Settings;
$db=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);Users::init($db);Settings::init($db);Settings::set($db,'company_domain','example.test');foreach(['alice','bob','carol'] as $name)Users::create($db,['username'=>$name,'display_name'=>ucfirst($name),'domain'=>'example.test','password'=>'test-password-123']);
$send=fn($key,$to,$cc,$permission=false,$transport=null)=>Dispatch::send($db,'employee:1',1,str_repeat($key,48),$to,$cc,'Subject','<p>Body</p>',$permission,$permission?['email'=>'alice@example.test']:null,null,sys_get_temp_dir(),null,[],'forward',$transport);
$r=$send('a','bob, carol','bob@example.test');assert($r['state']==='completed');assert(count($r['results'])===2);assert(count(InternalMail::list($db,2,'inbox'))===1);assert(count(InternalMail::list($db,3,'inbox'))===1);$again=$send('a','bob','');assert($again['duplicate_prevented']);assert(count(InternalMail::list($db,2,'inbox'))===1);echo "PASS: internal To/CC aliases deduplicate and repeated request does not resend\n";
try{$send('b','bob, stranger@outside.test','');throw new LogicException('Permission bypass');}catch(InvalidArgumentException $e){}assert(count(InternalMail::list($db,2,'inbox'))===1);echo "PASS: all destinations are validated before any internal delivery\n";
$calls=0;$r=$send('c','bob, one@outside.test','copy@outside.test',true,function($to,$extra,$cc)use(&$calls){$calls++;assert($to==='one@outside.test');assert($extra===[]);assert($cc===['copy@outside.test']);return '<smtp@example.test>';});assert($calls===1&&count($r['results'])===3);assert(count(InternalMail::list($db,2,'inbox'))===2);echo "PASS: mixed batch routes local recipient internally and external To/CC in one SMTP call\n";
$r=$send('d','carol, failed@outside.test','',true,fn()=>throw new RuntimeException('Transport failed'));assert($r['state']==='partial_or_unconfirmed');assert($r['results'][0]['status']==='delivered');assert($r['results'][1]['status']==='unconfirmed');assert($send('d','carol','')['duplicate_prevented']);assert(count(InternalMail::list($db,3,'inbox'))===2);echo "PASS: partial delivery is explicit and never automatically retried\n";assert(Dispatch::recent($db,'employee:2')===[]);assert(count(Dispatch::recent($db,'employee:1'))===3);echo "PASS: forward and send history is scoped to sender\n";

$calls=0;$r=$send('e','bob, unassigned@example.test','copy@example.test',true,function($to,$extra,$cc)use(&$calls){$calls++;assert($to==='unassigned@example.test');assert($extra===[]);assert($cc===['copy@example.test']);return '<fallback@example.test>';});assert($calls===1&&$r['state']==='completed'&&$r['results'][0]['route']==='internal'&&$r['results'][1]['route']==='smtp');echo "PASS: mixed company-domain batch sends unassigned addresses and CC via SMTP, assigned users locally\n";try{$send('f','no-user@example.test','',false);throw new LogicException('Permission bypass');}catch(InvalidArgumentException $e){}assert($calls===1);echo "PASS: company-domain fallback still requires external-send permission\n";
